// Office Open Source v0.1.7 - ONE user interface for the native (LibreOfficeKit) editor and the Web editor.
// ui_layout.json (embedded resource, generated by tools/ui_layout_gen.py from both ribbons) holds the tabs, groups, item
// order, labels and icons. The native ribbon keeps its own command implementations; items that only the Web editor
// implements are handed to the Web editor of the same file (and vice versa), so every button exists in both, in the
// same place, with the same picture.
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Globalization;
using System.IO;
using System.Reflection;
using System.Text;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;
using System.Windows.Forms;

namespace OfficeOpenSource
{
    static class UnifiedUi
    {
        static Dictionary<string, object> root; static bool loaded;
        public static Dictionary<string, object> Root
        {
            get
            {
                if (loaded) return root; loaded = true;
                try
                {
                    using (Stream s = Assembly.GetExecutingAssembly().GetManifestResourceStream("ui_layout.json"))
                    using (StreamReader r = new StreamReader(s, Encoding.UTF8))
                        root = new JavaScriptSerializer { MaxJsonLength = int.MaxValue }.Deserialize<Dictionary<string, object>>(r.ReadToEnd());
                }
                catch (Exception ex) { Lok.Trace("ui_layout: " + ex.Message); root = null; }
                return root;
            }
        }
        public static Dictionary<string, object> Layout(string kind) { Dictionary<string, object> r = Root; object o; return r != null && r.TryGetValue(kind, out o) ? o as Dictionary<string, object> : null; }
        static Dictionary<string, object> Lucide { get { Dictionary<string, object> r = Root; object o; return r != null && r.TryGetValue("lucide", out o) ? o as Dictionary<string, object> : null; } }
        public static bool HasLucide(string name) { Dictionary<string, object> l = Lucide; return l != null && l.ContainsKey(name); }

        // ---------------- Lucide (24x24 line icon) renderer: path / line / circle / rect / polyline / polygon / ellipse ----------------
        static readonly Dictionary<string, Bitmap> cache = new Dictionary<string, Bitmap>();
        public static void DrawLucide(Graphics g, string name, Rectangle r, bool enabled)
        {
            Dictionary<string, object> l = Lucide; object body; if (l == null || !l.TryGetValue(name, out body) || r.Width <= 0) return;
            string key = name + "|" + r.Width + "|" + enabled; Bitmap b;
            if (!cache.TryGetValue(key, out b))
            {
                b = new Bitmap(r.Width, r.Height);
                using (Graphics bg = Graphics.FromImage(b))
                {
                    bg.SmoothingMode = SmoothingMode.AntiAlias; bg.PixelOffsetMode = PixelOffsetMode.HighQuality;
                    float sc = r.Width / 24f; bg.ScaleTransform(sc, sc);
                    using (Pen pn = new Pen(enabled ? Color.FromArgb(0x42, 0x42, 0x42) : Color.FromArgb(0xA6, 0xA6, 0xA6), Math.Max(1.6f, 1.25f / sc * 1.6f)) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                        foreach (Match m in Regex.Matches((string)body, "<(path|line|circle|rect|polyline|polygon|ellipse)\\s([^>]*?)/?>"))
                        {
                            try
                            {
                                Dictionary<string, string> a = new Dictionary<string, string>();
                                foreach (Match am in Regex.Matches(m.Groups[2].Value, "([a-zA-Z-]+)=\"([^\"]*)\"")) a[am.Groups[1].Value] = am.Groups[2].Value;
                                using (GraphicsPath p = new GraphicsPath())
                                {
                                    switch (m.Groups[1].Value)
                                    {
                                        case "path": AddPath(p, Get(a, "d")); break;
                                        case "line": p.AddLine(F(a, "x1"), F(a, "y1"), F(a, "x2"), F(a, "y2")); break;
                                        case "circle": { float cx = F(a, "cx"), cy = F(a, "cy"), rr = F(a, "r"); p.AddEllipse(cx - rr, cy - rr, rr * 2, rr * 2); break; }
                                        case "ellipse": { float cx = F(a, "cx"), cy = F(a, "cy"), rx = F(a, "rx"), ry = F(a, "ry"); p.AddEllipse(cx - rx, cy - ry, rx * 2, ry * 2); break; }
                                        case "rect":
                                            {
                                                float x = F(a, "x"), y = F(a, "y"), w = F(a, "width"), h = F(a, "height"), rx = a.ContainsKey("rx") ? F(a, "rx") : 0;
                                                if (rx <= 0) p.AddRectangle(new RectangleF(x, y, w, h));
                                                else { float d = Math.Min(rx * 2, Math.Min(w, h)); p.AddArc(x, y, d, d, 180, 90); p.AddArc(x + w - d, y, d, d, 270, 90); p.AddArc(x + w - d, y + h - d, d, d, 0, 90); p.AddArc(x, y + h - d, d, d, 90, 90); p.CloseFigure(); }
                                                break;
                                            }
                                        case "polyline": case "polygon":
                                            {
                                                List<PointF> pts = new List<PointF>(); string[] t = Get(a, "points").Split(new[] { ' ', ',' }, StringSplitOptions.RemoveEmptyEntries);
                                                for (int i = 0; i + 1 < t.Length; i += 2) pts.Add(new PointF(N(t[i]), N(t[i + 1])));
                                                if (pts.Count > 1) { p.AddLines(pts.ToArray()); if (m.Groups[1].Value == "polygon") p.CloseFigure(); }
                                                break;
                                            }
                                    }
                                    bg.DrawPath(pn, p);
                                }
                            }
                            catch { }
                        }
                }
                cache[key] = b;
            }
            g.DrawImageUnscaled(b, r.X, r.Y);
        }
        static string Get(Dictionary<string, string> a, string k) { string v; return a.TryGetValue(k, out v) ? v : ""; }
        static float F(Dictionary<string, string> a, string k) { string v; return a.TryGetValue(k, out v) ? N(v) : 0f; }
        static float N(string s) { return float.Parse(s, CultureInfo.InvariantCulture); }

        // SVG path data -> GraphicsPath (M L H V C S Q T A Z, absolute and relative)
        static void AddPath(GraphicsPath p, string d)
        {
            List<string> tok = new List<string>();
            foreach (Match m in Regex.Matches(d, "[A-Za-z]|-?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?")) tok.Add(m.Value);
            int i = 0; char cmd = 'M'; PointF cur = PointF.Empty, start = PointF.Empty, lastCtl = PointF.Empty; char prev = ' ';
            Func<float> nx = () => N(tok[i++]);
            while (i < tok.Count)
            {
                if (char.IsLetter(tok[i][0])) { cmd = tok[i][0]; i++; if (cmd == 'Z' || cmd == 'z') { p.CloseFigure(); cur = start; prev = cmd; continue; } }
                bool rel = char.IsLower(cmd); char C = char.ToUpperInvariant(cmd);
                Func<float, float, PointF> P = (x, y) => rel ? new PointF(cur.X + x, cur.Y + y) : new PointF(x, y);
                switch (C)
                {
                    case 'M': { PointF q = P(nx(), nx()); p.StartFigure(); cur = start = q; cmd = rel ? 'l' : 'L'; break; }
                    case 'L': { PointF q = P(nx(), nx()); p.AddLine(cur, q); cur = q; break; }
                    case 'H': { float x = nx(); PointF q = new PointF(rel ? cur.X + x : x, cur.Y); p.AddLine(cur, q); cur = q; break; }
                    case 'V': { float y = nx(); PointF q = new PointF(cur.X, rel ? cur.Y + y : y); p.AddLine(cur, q); cur = q; break; }
                    case 'C': { PointF c1 = P(nx(), nx()), c2 = P(nx(), nx()), q = P(nx(), nx()); p.AddBezier(cur, c1, c2, q); lastCtl = c2; cur = q; break; }
                    case 'S': { PointF c1 = "CcSs".IndexOf(prev) >= 0 ? new PointF(2 * cur.X - lastCtl.X, 2 * cur.Y - lastCtl.Y) : cur; PointF c2 = P(nx(), nx()), q = P(nx(), nx()); p.AddBezier(cur, c1, c2, q); lastCtl = c2; cur = q; break; }
                    case 'Q': { PointF c = P(nx(), nx()), q = P(nx(), nx()); p.AddBezier(cur, Lerp(cur, c), Lerp(q, c), q); lastCtl = c; cur = q; break; }
                    case 'T': { PointF c = "QqTt".IndexOf(prev) >= 0 ? new PointF(2 * cur.X - lastCtl.X, 2 * cur.Y - lastCtl.Y) : cur; PointF q = P(nx(), nx()); p.AddBezier(cur, Lerp(cur, c), Lerp(q, c), q); lastCtl = c; cur = q; break; }
                    case 'A':
                        {
                            float rx = nx(), ry = nx(), rot = nx(), large = nx(), sweep = nx(); PointF q = P(nx(), nx());
                            Arc(p, cur, q, rx, ry, rot, large != 0, sweep != 0); cur = q; break;
                        }
                    default: i++; break;
                }
                prev = cmd;
            }
        }
        static PointF Lerp(PointF a, PointF c) { return new PointF(a.X + 2f / 3f * (c.X - a.X), a.Y + 2f / 3f * (c.Y - a.Y)); }
        // endpoint arc -> cubic Béziers (SVG implementation notes F.6)
        static void Arc(GraphicsPath p, PointF p1, PointF p2, double rx, double ry, double phiDeg, bool large, bool sweep)
        {
            if (rx == 0 || ry == 0) { p.AddLine(p1, p2); return; }
            double phi = phiDeg * Math.PI / 180, cs = Math.Cos(phi), sn = Math.Sin(phi);
            double dx = (p1.X - p2.X) / 2.0, dy = (p1.Y - p2.Y) / 2.0, x1 = cs * dx + sn * dy, y1 = -sn * dx + cs * dy;
            rx = Math.Abs(rx); ry = Math.Abs(ry); double lam = x1 * x1 / (rx * rx) + y1 * y1 / (ry * ry); if (lam > 1) { rx *= Math.Sqrt(lam); ry *= Math.Sqrt(lam); }
            double num = rx * rx * ry * ry - rx * rx * y1 * y1 - ry * ry * x1 * x1, den = rx * rx * y1 * y1 + ry * ry * x1 * x1;
            double co = Math.Sqrt(Math.Max(0, num / den)) * (large == sweep ? -1 : 1);
            double cxp = co * rx * y1 / ry, cyp = -co * ry * x1 / rx;
            double cx = cs * cxp - sn * cyp + (p1.X + p2.X) / 2.0, cy = sn * cxp + cs * cyp + (p1.Y + p2.Y) / 2.0;
            Func<double, double, double, double, double> ang = (ux, uy, vx, vy) => { double a = Math.Atan2(ux * vy - uy * vx, ux * vx + uy * vy); return a; };
            double t1 = ang(1, 0, (x1 - cxp) / rx, (y1 - cyp) / ry), dt = ang((x1 - cxp) / rx, (y1 - cyp) / ry, (-x1 - cxp) / rx, (-y1 - cyp) / ry);
            if (!sweep && dt > 0) dt -= 2 * Math.PI; else if (sweep && dt < 0) dt += 2 * Math.PI;
            int segs = (int)Math.Ceiling(Math.Abs(dt) / (Math.PI / 2)); double step = dt / segs, k = 4.0 / 3.0 * Math.Tan(step / 4);
            Func<double, PointF> pt = t => new PointF((float)(cx + rx * Math.Cos(t) * cs - ry * Math.Sin(t) * sn), (float)(cy + rx * Math.Cos(t) * sn + ry * Math.Sin(t) * cs));
            Func<double, PointF> dv = t => new PointF((float)(-rx * Math.Sin(t) * cs - ry * Math.Cos(t) * sn), (float)(-rx * Math.Sin(t) * sn + ry * Math.Cos(t) * cs));
            double ta = t1;
            for (int s = 0; s < segs; s++)
            {
                double tb = ta + step; PointF a = pt(ta), b2 = pt(tb), da = dv(ta), db = dv(tb);
                p.AddBezier(a, new PointF((float)(a.X + k * da.X), (float)(a.Y + k * da.Y)), new PointF((float)(b2.X - k * db.X), (float)(b2.Y - k * db.Y)), b2);
                ta = tb;
            }
        }
    }

    partial class NativeDocForm
    {
        readonly Dictionary<string, RItem> uiById = new Dictionary<string, RItem>();
        readonly Dictionary<string, Action> uiLaunch = new Dictionary<string, Action>();
        public static string PendingUiCmd;
        string KindName { get { return type == LokDoc.SPREADSHEET ? "excel" : type == LokDoc.PRESENTATION ? "ppt" : "word"; } }

        /// <summary>Re-arranges the ribbon built by BuildRibbon() into the shared layout (same as the Web editor).</summary>
        void ApplyUnifiedLayout()
        {
            Dictionary<string, object> lay = UnifiedUi.Layout(KindName); if (lay == null) return;
            Dictionary<string, RItem> idx = new Dictionary<string, RItem>(); Dictionary<string, Action> launch = new Dictionary<string, Action>();
            foreach (RTab t in ribbon.Tabs) foreach (RGroup g in t.Groups)
                {
                    if (g.Launcher != null && !launch.ContainsKey(g.Name)) launch[g.Name] = g.Launcher;
                    foreach (RItem i in g.All()) { string k = (i.Text ?? "") + "\u0001" + (i.Tip ?? ""); if (!idx.ContainsKey(k)) idx[k] = i; }
                }
            RTab file = ribbon.Tabs.Count > 0 && ribbon.Tabs[0].Name == "Tệp" ? ribbon.Tabs[0] : null;
            ribbon.Tabs.Clear(); if (file != null) ribbon.Tabs.Add(file); else ribbon.Tab("Tệp");
            uiById.Clear(); uiLaunch.Clear();
            foreach (object to in (System.Collections.IEnumerable)lay["tabs"])
            {
                Dictionary<string, object> t = (Dictionary<string, object>)to; string tname = (string)t["name"];
                if (Hidden(tname) && tname != "Trang đầu") continue;
                RTab rt = ribbon.Tab(tname);
                foreach (object go in (System.Collections.IEnumerable)t["groups"])
                {
                    Dictionary<string, object> g = (Dictionary<string, object>)go; string gname = (string)g["name"];
                    RGroup rg = rt.Add(gname); rg.Icon = Str(g, "icon");
                    string nl = Str(g, "nlauncher"), wl = Str(g, "wlauncher"); Action la;
                    if (nl != null && launch.TryGetValue(nl, out la)) rg.Launcher = la;
                    else if (wl != null) { string lid = "launcher:" + gname; rg.Launcher = () => OpenInWebCmd(lid); }
                    if (rg.Launcher != null) uiLaunch[gname] = rg.Launcher;
                    foreach (object co in (System.Collections.IEnumerable)g["cols"])
                    {
                        Dictionary<string, object> c = (Dictionary<string, object>)co; string ct = (string)c["type"];
                        if (ct == "rows")
                        {
                            List<RItem[]> rows = new List<RItem[]>();
                            foreach (object ro in (System.Collections.IEnumerable)c["rows"]) { List<RItem> r = new List<RItem>(); foreach (object eo in (System.Collections.IEnumerable)ro) r.Add(UiItem((Dictionary<string, object>)eo, idx, RK.Mini)); rows.Add(r.ToArray()); }
                            rg.Rows(rows.ToArray());
                            continue;
                        }
                        List<RItem> items = new List<RItem>(); foreach (object eo in (System.Collections.IEnumerable)c["items"]) items.Add(UiItem((Dictionary<string, object>)eo, idx, ct == "large" ? RK.Large : RK.Small));
                        if (ct == "large") rg.Large(items[0]);
                        else if (ct == "gallery") { if (items[0].Gallery != null) rg.Gallery(items[0]); else rg.Large(items[0]); }
                        else rg.Stack(items.ToArray());
                    }
                }
            }
            ribbon.Selected = 1;
        }
        static string Str(Dictionary<string, object> d, string k) { object o; return d.TryGetValue(k, out o) ? o as string : null; }
        RItem UiItem(Dictionary<string, object> e, Dictionary<string, RItem> idx, RK kind)
        {
            string id = Str(e, "id"), nat = Str(e, "nat"), icon = Str(e, "i"); RItem it = null;
            if (nat != null) idx.TryGetValue(nat, out it);
            if (it == null)
            {
                string label = Str(e, "t") ?? ""; string tip = Str(e, "tip");
                it = new RItem { Text = label, Tip = string.IsNullOrEmpty(tip) ? label : tip, Icon = icon, Kind = kind };
                string cid = id; it.Click = () => OpenInWebCmd(cid);
            }
            else if (!string.IsNullOrEmpty(icon)) it.Icon = icon;
            if (id != null) uiById[id] = it;
            return it;
        }

        /// <summary>Runs a Web-only command: the same file opens in the Web editor, which executes the command right away.</summary>
        void OpenInWebCmd(string id)
        {
            if (dirty) Save(true);
            try
            {
                if (App.OpenWindows.Count > 0) { App.AddPending(path, true, id); App.ActivateExistingWindow(); }
                else Process.Start(Application.ExecutablePath, "--web \"" + path + "\" --cmd " + id);
                status.Segs[0].Text = "Đang mở lệnh trong trình soạn Web…"; status.Invalidate();
            }
            catch (Exception ex) { MessageBox.Show(this, "Không mở được trình soạn Web: " + ex.Message, "Yomi-Office Open Source"); }
        }

        /// <summary>Command handed over by the Web editor (Windows): run the same ribbon item here.</summary>
        void RunUiCommand(string id)
        {
            try
            {
                if (id.StartsWith("bs:")) { RunBsCommand(id.Substring(3)); return; }
                if (id.StartsWith("launcher:")) { Action a; if (uiLaunch.TryGetValue(id.Substring(9), out a)) a(); return; }
                RItem it; if (!uiById.TryGetValue(id, out it) || it.Disabled) return;
                foreach (RTab t in ribbon.Tabs) foreach (RGroup g in t.Groups) foreach (RItem x in g.All()) if (x == it) { ribbon.Selected = ribbon.Tabs.IndexOf(t); ribbon.LayoutAll(); ribbon.Invalidate(); }
                if (it.Click != null) it.Click();
                else if (it.Menu != null) ribbon.ShowMenu(it.Menu, new Point(Math.Max(0, it.Bounds.X), it.Bounds.Bottom + 2));
            }
            catch (Exception ex) { Lok.Trace("ui cmd " + id + ": " + ex.Message); }
        }
    }
}
